<?php
declare(strict_types=1);
require dirname(__DIR__) . '/rado-system/lib/app.php';
session_name('rado_admin');session_set_cookie_params(['httponly'=>true,'secure'=>!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off','samesite'=>'Strict','path'=>'/']);session_start();
if(empty($_SESSION['admin_id'])){header('Location:/admin/');exit;}
$pdo=rado_db();
function h(string $v):string{return htmlspecialchars($v,ENT_QUOTES,'UTF-8');}
function cs():string{if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(24));return(string)$_SESSION['csrf'];}
function reqcs():void{if(!hash_equals((string)($_SESSION['csrf']??''),(string)($_POST['csrf']??''))){http_response_code(419);exit('CSRF');}}
function audit(PDO $pdo,string $action,string $type,string $id,array $after=[]):void{try{$pdo->prepare('INSERT INTO audit_logs(actor_user_id,actor_role,action,entity_type,entity_id,after_json,ip_address) VALUES(?,\'admin\',?,?,?,?,?)')->execute([(string)$_SESSION['admin_id'],$action,$type,$id,json_encode($after,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),(string)($_SERVER['REMOTE_ADDR']??'')]);}catch(Throwable){}}
$msg='';$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){reqcs();try{$a=(string)($_POST['action']??'');
 if($a==='save_dispatch'){foreach(['dispatch_radius_1_km','dispatch_radius_2_km','dispatch_radius_3_km','dispatch_batch_size','dispatch_offer_timeout_seconds','realtime_poll_seconds','loyalty_points_per_trip','referral_reward_amount'] as $k){if(isset($_POST[$k]))rado_set_setting($pdo,$k,trim((string)$_POST[$k]));}$msg='تنظیمات عملیات ذخیره شد.';audit($pdo,$a,'settings','dispatch',$_POST);}
 if($a==='save_integrations'){foreach(['otp_sms_webhook','fcm_server_key','online_payment_gateway','online_payment_api_key'] as $k){if(array_key_exists($k,$_POST)&&trim((string)$_POST[$k])!=='')rado_set_setting($pdo,$k,trim((string)$_POST[$k]));}$msg='تنظیمات سرویس‌های بیرونی ذخیره شد.';audit($pdo,$a,'settings','integrations',['otp_sms_webhook'=>!empty($_POST['otp_sms_webhook']),'fcm_server_key'=>!empty($_POST['fcm_server_key']),'online_payment_gateway'=>$_POST['online_payment_gateway']??'']);}
 if($a==='create_promo'){$code=strtoupper(trim((string)$_POST['code']));$title=trim((string)$_POST['title']);$type=in_array($_POST['discount_type']??'fixed',['fixed','percent'],true)?$_POST['discount_type']:'fixed';$value=(float)($_POST['discount_value']??0);if($code===''||$title===''||$value<=0)throw new RuntimeException('اطلاعات کد تخفیف کامل نیست.');$pdo->prepare('INSERT INTO promo_codes(code,title,discount_type,discount_value,max_discount,min_fare,total_limit,per_user_limit,active,starts_at,ends_at) VALUES(?,?,?,?,?,?,?,?,1,?,?)')->execute([$code,$title,$type,$value,($_POST['max_discount']??'')!==''?(int)$_POST['max_discount']:null,(int)($_POST['min_fare']??0),($_POST['total_limit']??'')!==''?(int)$_POST['total_limit']:null,max(1,(int)($_POST['per_user_limit']??1)),($_POST['starts_at']??'')?:null,($_POST['ends_at']??'')?:null]);$id=(string)$pdo->lastInsertId();$msg='کد تخفیف ساخته شد.';audit($pdo,$a,'promo',$id,$_POST);}
 if($a==='toggle_promo'){$id=(int)$_POST['id'];$pdo->prepare('UPDATE promo_codes SET active=1-active WHERE id=?')->execute([$id]);$msg='وضعیت کد تخفیف تغییر کرد.';audit($pdo,$a,'promo',(string)$id);}
 if($a==='create_mission'){$title=trim((string)$_POST['title']);$targetType=in_array($_POST['target_type']??'trips',['trips','online_minutes','revenue'],true)?$_POST['target_type']:'trips';$target=(int)($_POST['target_value']??0);$reward=(int)($_POST['reward_amount']??0);if($title===''||$target<=0)throw new RuntimeException('اطلاعات مأموریت کامل نیست.');$pdo->prepare('INSERT INTO driver_missions(title,description,target_type,target_value,reward_amount,starts_at,ends_at,active) VALUES(?,?,?,?,?,?,?,1)')->execute([$title,trim((string)($_POST['description']??''))?:null,$targetType,$target,$reward,(string)$_POST['starts_at'],(string)$_POST['ends_at']]);$id=(string)$pdo->lastInsertId();$msg='مأموریت راننده ساخته شد.';audit($pdo,$a,'mission',$id,$_POST);}
 if($a==='settlement'){$id=(int)$_POST['id'];$status=(string)$_POST['status'];if(!in_array($status,['approved','paid','rejected','cancelled'],true))throw new RuntimeException('وضعیت نامعتبر.');$sql=$status==='paid'?"UPDATE driver_settlements SET status='paid',reviewed_at=COALESCE(reviewed_at,NOW()),paid_at=NOW() WHERE id=?":"UPDATE driver_settlements SET status=?,reviewed_at=NOW() WHERE id=?";$s=$pdo->prepare($sql);$status==='paid'?$s->execute([$id]):$s->execute([$status,$id]);$msg='تسویه بروزرسانی شد.';audit($pdo,$a,'settlement',(string)$id,['status'=>$status]);}
 if($a==='reply_ticket'){$id=(int)$_POST['id'];$text=trim((string)$_POST['message']);if($text==='')throw new RuntimeException('متن پاسخ خالی است.');$pdo->prepare("INSERT INTO support_messages(ticket_id,sender_user_id,sender_role,message) VALUES(?,?,'admin',?)")->execute([$id,(string)$_SESSION['admin_id'],$text]);$pdo->prepare("UPDATE support_tickets SET status='waiting_user' WHERE id=?")->execute([$id]);$msg='پاسخ پشتیبانی ارسال شد.';audit($pdo,$a,'ticket',(string)$id);}
 if($a==='close_ticket'){$id=(int)$_POST['id'];$pdo->prepare("UPDATE support_tickets SET status='closed' WHERE id=?")->execute([$id]);$msg='تیکت بسته شد.';audit($pdo,$a,'ticket',(string)$id);}
 if($a==='create_area'){$title=trim((string)$_POST['title']);$type=in_array($_POST['area_type']??'service',['service','surcharge','blocked','outside_city'],true)?$_POST['area_type']:'service';$polygon=trim((string)$_POST['polygon_json']);json_decode($polygon,true,512,JSON_THROW_ON_ERROR);$pdo->prepare('INSERT INTO service_areas(title,area_type,polygon_json,fare_multiplier,flat_surcharge,active) VALUES(?,?,?,?,?,1)')->execute([$title,$type,$polygon,max(0.1,(float)($_POST['fare_multiplier']??1)),max(0,(int)($_POST['flat_surcharge']??0))]);$id=(string)$pdo->lastInsertId();$msg='محدوده سرویس ذخیره شد.';audit($pdo,$a,'service_area',$id);}
 if($a==='create_schedule'){$pdo->prepare('INSERT INTO pricing_schedules(title,days_of_week,start_time,end_time,multiplier,active,starts_at,ends_at) VALUES(?,?,?,?,?,1,?,?)')->execute([trim((string)$_POST['title']),trim((string)($_POST['days_of_week']??''))?:null,($_POST['start_time']??'')?:null,($_POST['end_time']??'')?:null,max(1,(float)($_POST['multiplier']??1)),($_POST['starts_at']??'')?:null,($_POST['ends_at']??'')?:null]);$id=(string)$pdo->lastInsertId();$msg='تعرفه زمانی ذخیره شد.';audit($pdo,$a,'pricing_schedule',$id);}
 if($a==='create_corporate'){$title=trim((string)$_POST['title']);if($title==='')throw new RuntimeException('نام حساب شرکتی الزامی است.');$pdo->prepare('INSERT INTO corporate_accounts(title,contact_phone,billing_mode,credit_limit,balance,active) VALUES(?,?,?,?,?,1)')->execute([$title,trim((string)($_POST['contact_phone']??''))?:null,in_array($_POST['billing_mode']??'prepaid',['prepaid','postpaid'],true)?$_POST['billing_mode']:'prepaid',(int)($_POST['credit_limit']??0),(int)($_POST['balance']??0)]);$id=(string)$pdo->lastInsertId();$msg='حساب شرکتی ساخته شد.';audit($pdo,$a,'corporate',$id);}
}catch(Throwable $e){$err=$e->getMessage();}}
$setting=function(string $k,string $d='')use($pdo){return h((string)(rado_setting($pdo,$k,$d)??$d));};
$promos=$pdo->query('SELECT * FROM promo_codes ORDER BY id DESC LIMIT 100')->fetchAll();$missions=$pdo->query('SELECT * FROM driver_missions ORDER BY id DESC LIMIT 100')->fetchAll();$settlements=$pdo->query("SELECT s.*,u.full_name FROM driver_settlements s JOIN users u ON u.id=s.driver_id ORDER BY s.id DESC LIMIT 100")->fetchAll();$tickets=$pdo->query("SELECT t.*,u.full_name FROM support_tickets t JOIN users u ON u.id=t.user_id ORDER BY FIELD(t.status,'open','waiting_admin','waiting_user','closed'),FIELD(t.priority,'urgent','high','normal','low'),t.updated_at DESC LIMIT 100")->fetchAll();$areas=$pdo->query('SELECT * FROM service_areas ORDER BY id DESC LIMIT 50')->fetchAll();$schedules=$pdo->query('SELECT * FROM pricing_schedules ORDER BY id DESC LIMIT 50')->fetchAll();$corporates=$pdo->query('SELECT * FROM corporate_accounts ORDER BY id DESC LIMIT 50')->fetchAll();$health=$pdo->query('SELECT * FROM health_events ORDER BY id DESC LIMIT 50')->fetchAll();$audit=$pdo->query('SELECT * FROM audit_logs ORDER BY id DESC LIMIT 50')->fetchAll();
?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>RADO Operations</title><style>:root{--g:#f5b400;--b:#171717;--bg:#f4f4f1}*{box-sizing:border-box}body{margin:0;background:var(--bg);font-family:Tahoma,Arial;color:#171717}.shell{max-width:1450px;margin:auto;padding:16px}.top{background:#171717;color:#fff;border-radius:24px;padding:20px;display:flex;justify-content:space-between;align-items:center}.logo{font-size:30px;font-weight:900}.gold{color:var(--g)}a{color:inherit}.tabs{display:flex;flex-wrap:wrap;gap:8px;margin:14px 0}.tabs a{background:#fff;padding:10px 14px;border-radius:99px;text-decoration:none}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.card{background:#fff;border-radius:22px;padding:18px;margin-bottom:14px;box-shadow:0 8px 25px #00000008}.card h3{margin-top:0}.fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}.full{grid-column:1/-1}label{font-size:12px;font-weight:800}input,select,textarea{width:100%;padding:11px;border:1px solid #ddd;border-radius:11px;margin-top:5px;background:#fff}textarea{min-height:90px}button{border:0;border-radius:11px;padding:11px 14px;background:#171717;color:#fff;font-weight:800}.goldbtn{background:var(--g);color:#171717}.notice{padding:12px 14px;border-radius:13px;margin:12px 0}.ok{background:#e8f7ec}.err{background:#fff0f0;color:#a21}.tablewrap{overflow:auto}.table{width:100%;border-collapse:collapse;min-width:800px}.table th,.table td{padding:9px;border-bottom:1px solid #eee;text-align:right;font-size:12px;vertical-align:top}.badge{display:inline-block;padding:4px 8px;border-radius:99px;background:#f0f0ee}.muted{color:#777;font-size:11px}.secret{border-color:#f5b400}@media(max-width:850px){.grid,.fields{grid-template-columns:1fr}.full{grid-column:auto}}</style></head><body><div class="shell"><div class="top"><div><div class="logo">R<span class="gold">A</span>DO OPERATIONS</div><div class="muted" style="color:#bbb"><?=h(rado_jalali_long())?> · Asia/Tehran</div></div><a href="/admin/" style="color:white">← پنل اصلی</a></div><?php if($msg):?><div class="notice ok"><?=h($msg)?></div><?php endif;?><?php if($err):?><div class="notice err"><?=h($err)?></div><?php endif;?>
<div class="tabs"><a href="#dispatch">Dispatch</a><a href="#promo">تخفیف</a><a href="#mission">مأموریت</a><a href="#settlement">تسویه</a><a href="#support">پشتیبانی</a><a href="#geo">محدوده</a><a href="#corporate">شرکتی</a><a href="#system">سیستم</a></div>
<div class="grid"><div><form class="card" id="dispatch" method="post"><input type="hidden" name="csrf" value="<?=h(cs())?>"><input type="hidden" name="action" value="save_dispatch"><h3>Dispatch و رشد</h3><div class="fields"><?php foreach(['dispatch_radius_1_km'=>'شعاع مرحله ۱ (km)','dispatch_radius_2_km'=>'شعاع مرحله ۲','dispatch_radius_3_km'=>'شعاع مرحله ۳','dispatch_batch_size'=>'راننده در هر Batch','dispatch_offer_timeout_seconds'=>'مهلت قبول (ثانیه)','realtime_poll_seconds'=>'Polling fallback (ثانیه)','loyalty_points_per_trip'=>'امتیاز هر سفر','referral_reward_amount'=>'پاداش معرفی (ریال)'] as $k=>$l):?><div><label><?=$l?></label><input name="<?=$k?>" value="<?=$setting($k)?>"></div><?php endforeach;?></div><button class="goldbtn">ذخیره تنظیمات</button></form>
<form class="card" method="post"><input type="hidden" name="csrf" value="<?=h(cs())?>"><input type="hidden" name="action" value="save_integrations"><h3>OTP / Push / پرداخت آنلاین</h3><p class="muted">مقادیر Secret پس از ذخیره دوباره نمایش داده نمی‌شوند.</p><label>SMS Webhook</label><input class="secret" name="otp_sms_webhook" placeholder="https://..."><label>FCM Server Key / credential</label><input class="secret" name="fcm_server_key" type="password"><label>نام درگاه پرداخت</label><input name="online_payment_gateway" value="<?=$setting('online_payment_gateway')?>"><label>API Key درگاه</label><input class="secret" name="online_payment_api_key" type="password"><button>ذخیره سرویس‌ها</button></form></div>
<div><form class="card" id="promo" method="post"><input type="hidden" name="csrf" value="<?=h(cs())?>"><input type="hidden" name="action" value="create_promo"><h3>کد تخفیف</h3><div class="fields"><div><label>کد</label><input name="code" required></div><div><label>عنوان</label><input name="title" required></div><div><label>نوع</label><select name="discount_type"><option value="fixed">مبلغ ثابت</option><option value="percent">درصد</option></select></div><div><label>مقدار</label><input name="discount_value" type="number" required></div><div><label>حداکثر تخفیف</label><input name="max_discount" type="number"></div><div><label>حداقل کرایه</label><input name="min_fare" type="number" value="0"></div><div><label>سقف کل</label><input name="total_limit" type="number"></div><div><label>سقف هر کاربر</label><input name="per_user_limit" type="number" value="1"></div><div><label>شروع (میلادی فنی)</label><input name="starts_at" placeholder="YYYY-MM-DD HH:MM:SS"></div><div><label>پایان</label><input name="ends_at" placeholder="YYYY-MM-DD HH:MM:SS"></div></div><button class="goldbtn">ساخت کد</button></form><div class="card"><div class="tablewrap"><table class="table"><tr><th>کد</th><th>عنوان</th><th>تخفیف</th><th>وضعیت</th><th></th></tr><?php foreach($promos as $p):?><tr><td><?=h($p['code'])?></td><td><?=h($p['title'])?></td><td><?=h($p['discount_type'])?> <?=h((string)$p['discount_value'])?></td><td><?=$p['active']?'فعال':'خاموش'?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=h(cs())?>"><input type="hidden" name="action" value="toggle_promo"><input type="hidden" name="id" value="<?=$p['id']?>"><button>تغییر</button></form></td></tr><?php endforeach;?></table></div></div></div></div>
<div class="grid"><div><form class="card" id="mission" method="post"><input type="hidden" name="csrf" value="<?=h(cs())?>"><input type="hidden" name="action" value="create_mission"><h3>مأموریت راننده</h3><div class="fields"><div><label>عنوان</label><input name="title" required></div><div><label>هدف</label><select name="target_type"><option value="trips">تعداد سفر</option><option value="revenue">درآمد</option><option value="online_minutes">دقایق آنلاین</option></select></div><div><label>مقدار هدف</label><input name="target_value" type="number" required></div><div><label>پاداش ریال</label><input name="reward_amount" type="number" value="0"></div><div><label>شروع</label><input name="starts_at" required placeholder="YYYY-MM-DD HH:MM:SS"></div><div><label>پایان</label><input name="ends_at" required placeholder="YYYY-MM-DD HH:MM:SS"></div><div class="full"><label>توضیح</label><textarea name="description"></textarea></div></div><button class="goldbtn">ساخت مأموریت</button></form><div class="card"><div class="tablewrap"><table class="table"><tr><th>عنوان</th><th>هدف</th><th>پاداش</th><th>پایان</th></tr><?php foreach($missions as $m):?><tr><td><?=h($m['title'])?></td><td><?=h($m['target_type'])?> / <?=number_format((int)$m['target_value'])?></td><td><?=number_format((int)$m['reward_amount'])?></td><td><?=h(rado_jalali_datetime((string)$m['ends_at']))?></td></tr><?php endforeach;?></table></div></div></div>
<div><div class="card" id="settlement"><h3>تسویه رانندگان</h3><div class="tablewrap"><table class="table"><tr><th>راننده</th><th>مبلغ</th><th>درخواست</th><th>وضعیت</th><th>عملیات</th></tr><?php foreach($settlements as $s):?><tr><td><?=h($s['full_name'])?></td><td><?=number_format((int)$s['amount'])?></td><td><?=h(rado_jalali_datetime((string)$s['requested_at']))?></td><td><?=h($s['status'])?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=h(cs())?>"><input type="hidden" name="action" value="settlement"><input type="hidden" name="id" value="<?=$s['id']?>"><select name="status"><option value="approved">تایید</option><option value="paid">پرداخت شد</option><option value="rejected">رد</option></select><button>ثبت</button></form></td></tr><?php endforeach;?></table></div></div></div></div>
<div class="card" id="support"><h3>پشتیبانی</h3><div class="tablewrap"><table class="table"><tr><th>کاربر</th><th>موضوع</th><th>اولویت</th><th>وضعیت</th><th>زمان</th><th>پاسخ</th></tr><?php foreach($tickets as $t):?><tr><td><?=h($t['full_name'])?></td><td><?=h($t['subject'])?></td><td><?=h($t['priority'])?></td><td><?=h($t['status'])?></td><td><?=h(rado_jalali_datetime((string)$t['created_at']))?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=h(cs())?>"><input type="hidden" name="action" value="reply_ticket"><input type="hidden" name="id" value="<?=$t['id']?>"><input name="message" placeholder="پاسخ"><button>ارسال</button></form><form method="post"><input type="hidden" name="csrf" value="<?=h(cs())?>"><input type="hidden" name="action" value="close_ticket"><input type="hidden" name="id" value="<?=$t['id']?>"><button>بستن</button></form></td></tr><?php endforeach;?></table></div></div>
<div class="grid"><div><form class="card" id="geo" method="post"><input type="hidden" name="csrf" value="<?=h(cs())?>"><input type="hidden" name="action" value="create_area"><h3>محدوده سرویس / Geofence</h3><label>عنوان</label><input name="title" required><label>نوع</label><select name="area_type"><option value="service">محدوده سرویس</option><option value="surcharge">افزایش کرایه</option><option value="blocked">مسدود</option><option value="outside_city">خارج شهر</option></select><label>Polygon JSON</label><textarea name="polygon_json" placeholder='[[45.88,35.99],[45.89,35.99],...]' required></textarea><div class="fields"><div><label>ضریب</label><input name="fare_multiplier" value="1"></div><div><label>مبلغ ثابت اضافه</label><input name="flat_surcharge" value="0"></div></div><button>ذخیره محدوده</button></form><div class="card"><ul><?php foreach($areas as $a):?><li><?=h($a['title'])?> · <?=h($a['area_type'])?> · ×<?=h((string)$a['fare_multiplier'])?></li><?php endforeach;?></ul></div></div>
<div><form class="card" method="post"><input type="hidden" name="csrf" value="<?=h(cs())?>"><input type="hidden" name="action" value="create_schedule"><h3>تعرفه زمانی</h3><label>عنوان</label><input name="title" required><label>روزهای هفته 1..7</label><input name="days_of_week" placeholder="1,2,3,4,5"><div class="fields"><div><label>از ساعت</label><input name="start_time" placeholder="17:00:00"></div><div><label>تا ساعت</label><input name="end_time" placeholder="21:00:00"></div><div><label>ضریب</label><input name="multiplier" value="1.2"></div></div><button>ذخیره تعرفه زمانی</button></form><div class="card"><ul><?php foreach($schedules as $s):?><li><?=h($s['title'])?> · ×<?=h((string)$s['multiplier'])?> · <?=h((string)$s['start_time'])?>–<?=h((string)$s['end_time'])?></li><?php endforeach;?></ul></div></div></div>
<div class="grid"><div><form class="card" id="corporate" method="post"><input type="hidden" name="csrf" value="<?=h(cs())?>"><input type="hidden" name="action" value="create_corporate"><h3>حساب سازمانی / شرکتی</h3><label>نام شرکت/هتل/فروشگاه</label><input name="title" required><label>تماس</label><input name="contact_phone"><label>مدل صورتحساب</label><select name="billing_mode"><option value="prepaid">پیش‌پرداخت</option><option value="postpaid">پس‌پرداخت</option></select><div class="fields"><div><label>اعتبار</label><input name="credit_limit" type="number" value="0"></div><div><label>موجودی</label><input name="balance" type="number" value="0"></div></div><button>ساخت حساب</button></form><div class="card"><ul><?php foreach($corporates as $c):?><li><?=h($c['title'])?> · <?=h($c['billing_mode'])?> · <?=number_format((int)$c['balance'])?> ریال</li><?php endforeach;?></ul></div></div>
<div><div class="card" id="system"><h3>Health Events</h3><div class="tablewrap"><table class="table"><tr><th>زمان</th><th>بخش</th><th>شدت</th><th>کد</th><th>پیام</th></tr><?php foreach($health as $x):?><tr><td><?=h(rado_jalali_datetime((string)$x['created_at']))?></td><td><?=h($x['component'])?></td><td><?=h($x['severity'])?></td><td><?=h($x['code'])?></td><td><?=h($x['message'])?></td></tr><?php endforeach;?></table></div></div><div class="card"><h3>Audit Log</h3><div class="tablewrap"><table class="table"><tr><th>زمان</th><th>نقش</th><th>عملیات</th><th>Entity</th></tr><?php foreach($audit as $x):?><tr><td><?=h(rado_jalali_datetime((string)$x['created_at']))?></td><td><?=h($x['actor_role'])?></td><td><?=h($x['action'])?></td><td><?=h((string)$x['entity_type'])?> / <?=h((string)$x['entity_id'])?></td></tr><?php endforeach;?></table></div></div></div></div>
</div></body></html>